const fs=require('fs');
function patch(path){let s=fs.readFileSync(path,'utf8');if(!s.includes('UNIVERSAL_SKILL_EXECUTION_SANDBOX_TOOL_DECLARATION'))throw new Error(`sandbox tool declaration missing: ${path}`);if(!s.includes('universalSkillExecutionSandboxManager'))throw new Error(`sandbox manager missing: ${path}`);const marker='else if (name === "skill_benchmark_runner")';if(!s.includes(marker))throw new Error(`runner dispatcher missing: ${path}`);if(!s.includes('else if (name === "skill_execution_sandbox")')){const backend=path.includes('Mastermind_Desktop')?'process':'docker';const branch=`else if (name === "skill_execution_sandbox") toolResult = await universalSkillExecutionSandboxManager(args?.action || "validate", args || {}, { execute: async (command,meta) => {\n    if (typeof callLocalBridge !== 'function') throw new Error('local execution bridge unavailable');\n    const raw = await callLocalBridge('cmd',{ command, timeoutMs:meta?.timeoutMs, workingDirectory:meta?.workingDirectory });\n    return { ...raw, isolation:{ level:'${backend==='docker'?'container-isolated':'process-isolated'}', backend:'${backend}', network:'disabled' } };\n} });\n`;s=s.replace(marker,branch+marker);}fs.writeFileSync(path,s);}
patch('my_AI/ai_engine_core.js');patch('Mastermind_Desktop/core.js');
console.log('sandbox dispatcher patched');
